Diberikan fungsi seperti di bawah ini. Berapakah nilai yang dikembalikan dari pemanggilan fungsi cariNilai(2017,1017) ? function cariNilai(n, x: integer): longint;
var
 i: integer;
 n_now, x_now: integer;
 ans: longint;
begin
 ans := 0;
 n_now := n;
 x_now := x;
 while (n_now > 0) do begin
 ans := ans + x_now;
 x_now := x_now - 1;
 n_now := n_now - 1;
 end;
 cariNilai := ans;
end;

Diberikan fungsi seperti di bawah ini. Berapakah nilai dari f(8, 9, 4, 5, 6, 10000) ? function f (a, b , pa, pb, pab, n: longint): longint;
var
 total: long int;
 i: long int;
begin
 i := 0;
 total := 0;
 while (total < n) do
 begin
 i := i + 1;
 if (i mod a = 0) and (i mod b = 0) then
 total := total + pab
 else if i mod a = 0 then
 total := total + pa
 else if i mod b = 0 then
 total := total + pb;
 end;
 f := i;
end;

